    if lhs.imgLabelUriHant != rhs.imgLabelUriHant {return false}
    if lhs.imgLabelUriHansStatic != rhs.imgLabelUriHansStatic {return false}
    if lhs.imgLabelUriHantStatic != rhs.imgLabelUriHantStatic {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
